import random
import math
from fractions import Fraction

def generate_random_branching_program(n):
    program = []
    for _ in range(n):
        if random.choice([True, False]):
            program.append('0')
        else:
            program.append('1')
    return program

def construct_configuration_space(P):
    n = len(P)
    CS = [[[] for _ in range(2)] for _ in range(n)]
    CS[0][int(P[0])].append(0)

    for i in range(1, n):
        for j in range(2):
            if j == int(P[i]):
                CS[i][j] = [x + 1 for x in CS[i-1][j]]
            else:
                CS[i][j] = [x + 1 for x in CS[i-1][j]] + [0]

    return CS

def min_local_index(CS):
    n = len(CS)
    indices = []
    for i in range(n):
        if CS[i][0]:
            indices.append(min(CS[i][0]))
        if CS[i][1]:
            indices.append(min(CS[i][1]))
    return min(indices)

def run_trial(seed: int) -> dict:
    random.seed(seed)

    n_values = [5, 10, 15, 20, 30, 40]
    total_metric_value = 0
    instances_tested = 0

